'use server'

import { revalidatePath } from 'next/cache'

/**
 * Toggle user notification preference
 * @returns The new notification preference state
 */
export async function toggleNotifications(): Promise<boolean> {
  // In a real application, this would update the user's preference in a database
  // For this example, we'll simulate toggling a preference
  const currentPreference = Math.random() > 0.5

  // Simulate some async operation (like database update)
  await new Promise(resolve => setTimeout(resolve, 100))

  // In a real app, you would save this to your database
  // For demo purposes, we're just returning the opposite of current preference
  const newPreference = !currentPreference

  // Revalidate the current page to show the updated preference
  revalidatePath('/settings')

  return newPreference
}

