import { toggleNotifications } from '../actions/toggle-notifications'

export default async function NotificationToggle() {
  // In a real application, you would fetch the current preference from a database
  // For this demo, we'll simulate getting the current preference
  const currentPreference = Math.random() > 0.5

  return (
    <div className="max-w-md mx-auto mt-8 p-6 bg-white rounded-lg shadow-md">
      <h2 className="text-2xl font-bold mb-4 text-gray-800">Notification Settings</h2>

      <div className="space-y-4">
        <div className="flex items-center justify-between p-4 bg-gray-50 rounded-lg">
          <div>
            <h3 className="text-lg font-medium text-gray-900">Email Notifications</h3>
            <p className="text-sm text-gray-600">Receive updates about your account</p>
          </div>

          <form action={toggleNotifications}>
            <button
              type="submit"
              className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                currentPreference ? 'bg-blue-600' : 'bg-gray-200'
              }`}
            >
              <span
                className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                  currentPreference ? 'translate-x-6' : 'translate-x-1'
                }`}
              />
            </button>
            <input type="hidden" name="currentPreference" value={currentPreference.toString()} />
          </form>
        </div>

        <div className="text-sm text-gray-600">
          Current status: {currentPreference ? 'Enabled' : 'Disabled'}
        </div>

        <div className="text-xs text-gray-500">
          Note: This is a demo. In a real application, preferences would be saved to a database.
        </div>
      </div>
    </div>
  )
}

